PAGES=[page('083_page_2.jpg',158,[heading('Substitution solution — continuation from missing page 157'),paragraph('Now, use trigonometric substitutions in equation (ii)'),eq(r'u=\tan\theta,\quad\frac{du}{d\theta}=\sec^2\theta\Rightarrow du=\sec^2\theta\,d\theta'),eq(r'\int\frac{u}{u^2+1}\,du=\int\frac{\tan\theta\sec^2\theta}{\tan^2\theta+1}\,d\theta=\int\tan\theta\,d\theta=\int\frac{\sin\theta}{\cos\theta}\,d\theta=-\ln|\cos\theta|+C','iii'),paragraph('Return substitutions in (iii)'),eq(r'\int\frac{x+2}{x^2+4x+5}\,dx=-\ln|\cos(\tan^{-1}u)|+C'),eq(r'=-\ln\left|\frac{\sqrt{1+u^2}}{1+u^2}\right|+C=-\ln\left|\frac{\sqrt{1+(x+2)^2}}{1+(x+2)^2}\right|+C'),eq(r'=-\ln\left|\frac1{\sqrt{1+(x+2)^2}}\right|+C=-\ln|[1+(x+2)^2]^{-1/2}|+C'),eq(r'=\frac12\ln|1+(x+2)^2|+C'),paragraph('Hence,'),eq(r'\int\frac{x+2}{x^2+4x+5}\,dx=\frac12\ln|1+(x+2)^2|+C=\frac12\ln|x^2+4x+5|+C'),note('The preceding page containing this example’s opening is unavailable in all supplied source formats. This continuation is transcribed without inventing the missing source. The denominator (x+2)²+1 is positive on ℝ, so the absolute value can be removed in the learning result.'),heading('Example 9'),paragraph(r'Evaluate the integral \(\int\frac{x+2}{\sqrt{x^2+4x+5}}\,dx\).'),heading('Solution'),eq(r'\int\frac{x+2}{\sqrt{x^2+4x+5}}\,dx','i'),paragraph('By completing square in denominator'),eq(r'\int\frac{x+2}{\sqrt{x^2+4x+4+1}}\,dx=\int\frac{x+2}{\sqrt{(x+2)^2+1}}\,dx'),paragraph('Let u = x+2, du/dx = 1 and du = dx'),eq(r'\int\frac{x+2}{\sqrt{(x+2)^2+1}}\,dx=\int\frac{u}{\sqrt{u^2+1}}\,du','ii'),paragraph('Now, use trigonometric substitutions in equation (ii)'),eq(r'u=\tan\theta,\quad du=\sec^2\theta\,d\theta'),eq(r'\int\frac{u}{\sqrt{u^2+1}}\,du=\int\frac{\tan\theta\sec^2\theta}{\sqrt{\tan^2\theta+1}}\,d\theta=\int\tan\theta\sec\theta\,d\theta=\sec\theta+C','iii'),paragraph('Return substitutions in (iii)')
]),page('084_page_1.jpg',159,[heading('Example 9 — solution continued'),eq(r'\int\frac{x+2}{\sqrt{x^2+4x+5}}\,dx=\sec(\tan^{-1}u)+C=\sqrt{1+u^2}+C=\sqrt{1+(x+2)^2}+C'),paragraph('Hence,'),eq(r'\int\frac{x+2}{\sqrt{x^2+4x+5}}\,dx=\sqrt{x^2+4x+5}+C'),heading('6.4 Integration by Parts'),paragraph('In previous sections, we have learnt some of the basic techniques of integration to solve problems like ∫x²dx and ∫sinxdx. But, how do we evaluate an integral whose integrand is the product of two functions such as ∫xsinxdx, ∫xeˣdx, ∫xlnxdx'),paragraph('To solve integral of the type like that, we have a technique called integration by parts.'),heading('6.4.1 Recognition of integration by parts'),paragraph('For this technique, recall the differentiation of the product of two functions f(x) and g(x) w.r.t x:'),eq(r'\frac d{dx}[f(x)g(x)]=f(x)\frac d{dx}g(x)+g(x)\frac d{dx}f(x)=f(x)g′(x)+g(x)f′(x)'),eq(r'f(x)g′(x)=\frac d{dx}[f(x)g(x)]-g(x)f′(x)','i'),paragraph('The integral of (i) with respect to x is giving'),eq(r'\int f(x)g′(x)\,dx=\int\frac d{dx}[f(x)g(x)]\,dx-\int g(x)f′(x)\,dx=f(x)g(x)-\int g(x)f′(x)\,dx'),paragraph('The equation that can be transformed into more convenient form by substituting u = f(x) and v = g(x), du = f′(x)dx and dv = g′(x)dx:'),eq(r'\int u\,dv=uv-\int v\,du','ii'),paragraph('This is the standard form of the integration by parts formula.'),heading('Example 10'),paragraph(r'Evaluate the integral \(\int xe^x\,dx\).'),heading('Solution'),paragraph('The integral rule (ii) with u = x and dv/dx = eˣ is used to obtain:'),eq(r'\int xe^x\,dx=xe^x-\int e^x(1)\,dx,\quad\frac{du}{dx}=1,\quad dv=e^x\,dx,\quad v=e^x'),eq(r'=xe^x-e^x+C'),heading('6.4.2 Applying method of integration by parts to evaluate integrals of the following types'),eq(r'\int\sqrt{a^2-x^2}\,dx,\quad\int\sqrt{a^2+x^2},\quad\int\sqrt{x^2-a^2}'),heading('i. Evaluate ∫√(a²−x²) dx'),heading('Solution'),paragraph('The given integral is'),eq(r'I=\int\sqrt{a^2-x^2}\,dx','i'),paragraph('In this problem, we choose u = √(a²−x²) and dv/dx = 1 to integrate the integrand of (i):'),eq(r'I=x\sqrt{a^2-x^2}-\int\frac{x(-x)}{\sqrt{a^2-x^2}}\,dx,\quad\frac{du}{dx}=\frac12(a^2-x^2)^{-1/2}(-2x),\quad dv=dx,\quad v=x'),eq(r'=x\sqrt{a^2-x^2}+\int\frac{x^2}{\sqrt{a^2-x^2}}\,dx=x\sqrt{a^2-x^2}+\int\frac{a^2-(a^2-x^2)}{\sqrt{a^2-x^2}}\,dx'),paragraph('add and subtract a²')])]
